/* ============================================================
   أطياب الجاسم (React) — بيانات الصفحة (usePageMeta)

   كل صفحة صارت هي المسؤولة عن نفسها: تُنادي هذا الخطّاف في أوّلها
   فتُعلن اسمها (data-route) وكتالوجها (data-catalog) وعنوان تبويب
   المتصفّح — بدل أن يعرف App كم صفحة وكيف تسمّى كل واحدة.

   ★ الخطّاف يقرأ اللغة من Redux بنفسه، فعنوان التبويب يتبدّل فوراً
     عند تغيير اللغة بلا أي كود إضافي في الصفحة.
   ------------------------------------------------------------
     usePageMeta({ route: "offers", catalog: "", titleAr: "العروض", titleEn: "Offers" })
   ★ `active: false` تعني أنّ الصفحة مُركَّبة لكنها مخفيّة (الرئيسية تبقى
     مُركَّبة دائماً داخل .route-slot) — فلا تكتب عنوانها ولا data-route
     وهي مخفيّة، وتُعيد كتابتهما بمجرد أن تعود نشطة.
   ============================================================ */

import { useEffect, useMemo } from "react";
import { useAppSelector } from "./redux/hooks.js";

const BASE_TITLE_AR = "أطياب الجاسم — العطور والبخور";
const BASE_TITLE_EN = "Atyab Al-Jasem — Perfumes & Bakhoor";
const SITE_URL = "https://atyabaljasim.com";
const DEFAULT_DESC_AR = "متجر أطياب الجاسم: عطور شرقية وبخور فاخر — تشكيلة العطور والبخور مع التفاصيل والأسعار والتقييمات وعربة التسوق.";
const DEFAULT_DESC_EN = "Atyab Al-Jasem store: oriental perfumes and luxury bakhoor — collections with details, prices, reviews and cart.";

/* عنوان التبويب: «اسم الصفحة — اسم المتجر» (وبدونه للصفحة الرئيسية).
   ★ SEO: العنوان الجاهز (يحمل اسم المتجر أو |) يُستخدم كما هو بلا لاحقة. */
export function pageTitle(title, language) {
  const base = language === "en" ? BASE_TITLE_EN : BASE_TITLE_AR;
  if (!title) return base;
  if (title.indexOf("أطياب الجاسم") !== -1 || title.indexOf("Atyab Al-Jasem") !== -1 || title.indexOf("|") !== -1) return title;
  return title + " — " + base;
}

/* ★ SEO: تحديث/إنشاء وسم meta أو link — يعمل مع prerender وغوغل */
function setMeta(attr, name, content) {
  try {
    let el = document.head.querySelector("meta[" + attr + '="' + name + '"]');
    if (!el) {
      el = document.createElement("meta");
      el.setAttribute(attr, name);
      document.head.appendChild(el);
    }
    el.setAttribute("content", content);
  } catch (e) {}
}

function setLink(rel, href) {
  try {
    let el = document.head.querySelector('link[rel="' + rel + '"]');
    if (!el) {
      el = document.createElement("link");
      el.setAttribute("rel", rel);
      document.head.appendChild(el);
    }
    el.setAttribute("href", href);
  } catch (e) {}
}

export function usePageMeta(meta) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const routeKey = (meta && meta.route) || "";
  const catalogKey = (meta && meta.catalog) || "";
  const titleAr = meta && meta.titleAr;
  const titleEn = meta && meta.titleEn;
  /* ★ SEO: وصف الصفحة (meta description) يظهر تحت الرابط في غوغل —
     بدونه يعرض غوغل أول نص يجده. والـcanonical يمنع ازدواج الفهرسة. */
  const descAr = (meta && meta.descAr) || DEFAULT_DESC_AR;
  const descEn = (meta && meta.descEn) || DEFAULT_DESC_EN;
  const canonicalPath = meta && meta.canonical;
  const active = !meta || meta.active !== false;

  const title = useMemo(
    function () {
      return pageTitle(language === "en" ? titleEn : titleAr, language);
    },
    [language, titleAr, titleEn],
  );
  const desc = language === "en" ? descEn : descAr;

  useEffect(
    function () {
      if (!active) return;
      document.title = title;
      /* وصف المشاركة/البحث + og/twitter */
      const content = String(desc || "").slice(0, 300);
      setMeta("name", "description", content);
      setMeta("property", "og:title", title);
      setMeta("property", "og:description", content);
      setMeta("name", "twitter:title", title);
      setMeta("name", "twitter:description", content);
      /* canonical مطلق لمسار الصفحة الحالي (أو الممرَّر صراحةً) */
      let path = canonicalPath;
      if (!path) {
        try {
          path = window.location.pathname || "/";
        } catch (e) {
          path = "/";
        }
      }
      const url = SITE_URL + (path.charAt(0) === "/" ? path : "/" + path);
      setLink("canonical", url);
      setMeta("property", "og:url", url);
    },
    [title, desc, canonicalPath, active],
  );

  useEffect(
    function () {
      if (!active) return;
      const root = document.documentElement;
      root.setAttribute("data-route", routeKey);
      root.setAttribute("data-catalog", catalogKey);
    },
    [routeKey, catalogKey, active],
  );

  return title;
}
