/* ============================================================
   أطياب الجاسم (React) — مسرح «رونق» الافتتاحي (RawnaqScene)

   كومبوننت JS أصيل بنفس عقد المشاهد الأخرى (2DPerfumeView /
   Bakhour3D): يُبنى بـReact ويُركَّب كسولًا عبر SceneSlot، بلا
   iframe وبلا ملف HTML خارجي.

   البنية (مطابقة لملف المالك الأصلي):
     خلفية المسرح + عبوة رونق (بقناع قصّ) + دخان حيّ (فيديو
     خفي → canvas بفلترة لمعان-إلى-شفافية) + 14 قطعة عود SVG
     + زرّ تشغيل/إيقاف البخار.
   ============================================================ */

import { useEffect, useId, useRef, useState } from "react";
import "./RawnaqScene.css";

const PUB = (process.env.PUBLIC_URL || "");
const BACKDROP_SRC = PUB + "/rawnaq/stage-backdrop.png";
const JAR_SRC = PUB + "/rawnaq/rawnaq-jar.png";
const WOOD_SRC = PUB + "/rawnaq/oud-wood.png";
const SMOKE_SRC = PUB + "/rawnaq/smoke.mp4";

/* قطع العود الـ14: (x, y, w, h, دوران، الرمز) — نفس قيم المالك */
const WOOD_PIECES = [
  [4.9574, 92.0381, 4.7337, 3.3364, 3.72, 0],
  [13.6795, 94.6497, 5.2581, 3.7075, 29.88, 1],
  [21.7518, 91.4966, 5.5199, 3.7201, 4.50, 2],
  [31.3434, 93.0468, 4.8914, 3.7666, 31.74, 0],
  [40.7557, 90.2378, 5.2073, 3.4404, -28.02, 1],
  [48.9948, 94.6000, 6.1120, 3.4574, 8.55, 2],
  [59.4591, 91.5007, 3.9334, 3.3622, 6.78, 0],
  [69.0422, 94.6063, 3.9079, 3.0951, 15.59, 1],
  [78.4198, 91.9216, 5.8558, 3.5694, 11.13, 2],
  [88.0159, 94.4826, 6.3902, 3.6922, -27.63, 0],
  [33.3694, 78.6437, 4.5504, 2.5029, 26.13, 1],
  [60.1053, 78.1489, 5.5707, 2.7931, -20.52, 2],
  [3.3064, 83.9621, 4.1294, 3.4045, -1.21, 0],
  [93.2023, 82.7028, 3.4392, 3.4756, -13.66, 1]
];

const CUTOUT_PATH = "M 189 278 L 215 277 L 215 260 L 248 244 L 242 235 L 257 225 L 286 231 L 355 211 Q 370 206 375 216 L 382 230 L 365 244 L 432 222 L 440 225 L 437 245 L 462 253 L 469 263 L 487 259 L 500 266 L 483 290 Q 525 294 526 305 L 527 353 Q 581 368 590 400 L 589 412 Q 652 469 666 579 Q 676 642 668 731 L 665 741 L 669 760 L 666 788 Q 688 844 666 894 Q 642 956 570 966 Q 531 970 490 948 L 476 935 Q 257 946 110 933 Q 45 916 25 858 L 17 837 L 15 748 L 17 737 Q 10 696 14 637 Q 17 495 92 418 L 91 407 Q 89 380 151 357 L 154 310 Q 153 299 179 295 L 198 292 Z";

export default function RawnaqScene() {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const [playing, setPlaying] = useState(true);

  useEffect(function () {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return undefined;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return undefined;

    let raf = 0;
    let last = -1;
    let alive = true;

    video.defaultPlaybackRate = 0.75;
    video.playbackRate = 0.75;

    function draw() {
      if (!alive) return;
      try {
        if (video.readyState >= 2 && last !== video.currentTime) {
          last = video.currentTime;
          ctx.clearRect(0, 0, 400, 388);
          ctx.drawImage(video, 0, 0, 400, 388);
          const frame = ctx.getImageData(0, 0, 400, 388);
          const d = frame.data;
          for (let i = 0; i < d.length; i += 4) {
            const l = Math.max(d[i], d[i + 1], d[i + 2]);
            d[i + 3] = Math.max(0, (l - 12) / 243) * 240;
            d[i] = 245; d[i + 1] = 245; d[i + 2] = 242;
          }
          ctx.putImageData(frame, 0, 0);
        }
      } catch (e) { /* فيديو غير جاهز بعد — تُعاد المحاولة الإطار القادم */ }
      raf = requestAnimationFrame(draw);
    }
    draw();

    let startPaused = false;
    try {
      startPaused = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    } catch (e) {}
    if (startPaused) {
      try { video.pause(); } catch (e) {}
      setPlaying(false);
    } else {
      try {
        const p = video.play();
        if (p && typeof p.catch === "function") {
          p.catch(function () { setPlaying(false); });
        }
      } catch (e) { setPlaying(false); }
    }

    return function () {
      alive = false;
      try { cancelAnimationFrame(raf); } catch (e) {}
      try { video.pause(); } catch (e) {}
    };
  }, []);

  function toggle() {
    const video = videoRef.current;
    if (!video) return;
    try {
      if (video.paused) { video.play(); setPlaying(true); }
      else { video.pause(); setPlaying(false); }
    } catch (e) {}
  }

  const woodId = "rawnaq-wood-" + uid;
  const cutId = "rawnaq-cutout-" + uid;

  return (
    <div className="void-frame showcase-media rawnaq-frame">
      <span className="scene-tag">
        <i /> مسرح أطياب الجاسم · مشهد حيّ
      </span>
      <div className="rawnaq-stage" role="img" aria-label="عبوة بخور رونق على منصة أطياب الجاسم مع دخان متحرك">
        <svg width="0" height="0" aria-hidden="true" style={{ position: "absolute" }}>
          <defs>
            <image id={woodId} width="1000" height="1000" href={WOOD_SRC} />
            <clipPath id={woodId + "-clip-0"}>
              <polygon points="370,269 391,246 454,230 462,241 515,212 553,195 689,181 707,187 714,202 696,224 678,245 615,275 563,289 500,300 445,293 388,287 371,279" />
            </clipPath>
            <symbol id={woodId + "-0"} viewBox="365 175 355 135">
              <use href={"#" + woodId} clipPath={"url(#" + woodId + "-clip-0)"} />
            </symbol>
            <clipPath id={woodId + "-clip-1"}>
              <polygon points="524,367 565,340 607,316 664,300 714,294 770,295 820,300 828,318 823,341 768,348 721,357 666,369 599,376 552,381" />
            </clipPath>
            <symbol id={woodId + "-1"} viewBox="518 290 315 100">
              <use href={"#" + woodId} clipPath={"url(#" + woodId + "-clip-1)"} />
            </symbol>
            <clipPath id={woodId + "-clip-2"}>
              <polygon points="403,693 448,670 508,659 564,658 625,664 687,667 755,677 809,689 845,704 865,717 850,726 797,718 742,713 678,719 611,723 542,718 477,715 426,712" />
            </clipPath>
            <symbol id={woodId + "-2"} viewBox="396 652 475 77">
              <use href={"#" + woodId} clipPath={"url(#" + woodId + "-clip-2)"} />
            </symbol>
          </defs>
        </svg>
        <img className="rawnaq-backdrop" alt="مسرح أطياب الجاسم الأصلي" src={BACKDROP_SRC} />
        <canvas ref={canvasRef} className="rawnaq-smoke" width="400" height="388" aria-label="البخار الجديد" />
        <video ref={videoRef} className="rawnaq-video" muted autoPlay playsInline loop preload="auto" src={SMOKE_SRC} />
        <svg className="rawnaq-product" viewBox="0 0 683 1024" role="img" aria-label="عبوة بخور رونق دون الخلفية البيضاء">
          <defs>
            <mask id={cutId} maskUnits="userSpaceOnUse" x="0" y="0" width="683" height="1024">
              <path d={CUTOUT_PATH} fill="white" stroke="black" strokeWidth="5" />
            </mask>
          </defs>
          <image width="683" height="1024" href={JAR_SRC} mask={"url(#" + cutId + ")"} />
        </svg>
        {WOOD_PIECES.map(function (p, i) {
          return (
            <svg
              key={i}
              className="rawnaq-wood"
              role="img"
              aria-label="قطعة عود"
              style={{
                left: p[0] + "%", top: p[1] + "%",
                width: p[2] + "%", height: p[3] + "%",
                transform: "rotate(" + p[4] + "deg)"
              }}
            >
              <use href={"#" + woodId + "-" + p[5]} width="100%" height="100%" />
            </svg>
          );
        })}
        <button className="rawnaq-play" type="button" onClick={toggle}>
          {playing ? "إيقاف البخار" : "تشغيل البخار"}
        </button>
      </div>
    </div>
  );
}
